#' Generate and return all permutations of a multiset
#' 
#' This function will return all permutations of a multiset
#' 
#' This function will return all permutations of a multiset. It makes no check
#' to see if this is a sensible thing to do. Users are advised to check how
#' many permutations are possible using the \code{multinom} function in this
#' package.
#' 
#' @param mcObj an object of class mc - usually generated by \code{initMC}
#' @param nThreads the number of threads to use. Using more than one only
#' helps for large results (at least 100,000 permutations; smaller results are
#' always generated with one thread), and only for integer, double and logical
#' multisets, and multisets of other types that are mapped from integer codes,
#' such as Dates. Character and factor multisets always use one thread. The
#' gain is limited by memory bandwidth, so it is usually well short of
#' \code{nThreads} times faster.
#' @return A matrix with each row being a different permutation of the multiset
#' @note This function does not warn the user that the requested set of
#' permutations may be very large. In addition, all working is handled entirely
#' in memory, and so this may cause it to crash if the request is
#' execeptionally large. \code{\link{nextPerm}} can step through the
#' permutations in batches instead, without holding them all in memory.
#' @author James M. Curran
#' @seealso \code{\link{initMC}}, \code{\link{multinom}}, \code{\link{nextPerm}}
#' @keywords permutations
#' @examples
#' 
#' ## a small numeric example with 6 permuations
#' x = c(1,1,2,2)
#' m = initMC(x)
#' allPerm(m)
#' 
#' ## a large character example - 60 possibilities
#' x = rep(letters[1:3], 3:1)
#' multinom(x) ## calculate the number of permutations
#' m = initMC(x)
#' allPerm(m)
#' 
#' ## 362,880 permutations, using two threads
#' m = initMC(1:9)
#' p = allPerm(m, nThreads = 2)
#' dim(p)
#' 
#' @export allPerm
allPerm = function(mcObj, nThreads = 1){
    if(!inherits(mcObj, "mc")){
      stop("mcObj must be of class mc")
    }
    
    if(!is.numeric(nThreads) || length(nThreads) != 1 || is.na(nThreads) ||
       nThreads < 1 || nThreads != round(nThreads) ||
       nThreads > .Machine$integer.max){
      stop("nThreads must be a single positive integer")
    }
    
    ## the number of permutations is the multinomial coefficient of the
    ## multiplicities, which lets the C++ code fill a matrix of the right size
    nPerms = multinom(mcObj$set)
    if(nPerms > .Machine$integer.max)
      stop("there are too many permutations (", as.character(nPerms),
           ") to return them all")
    
    nPerms = as.integer(as.numeric(nPerms))
    nThreads = as.integer(nThreads)
    
    ## a matrix of factors would be a character matrix anyway, and character
    ## vectors can be written straight into the result by the C++ code
    elements = mcObj$elements
    if(is.factor(elements))
      elements = as.character(elements)
    
    if(isPlainElements(elements))
      return(mcAllPerm(mcObj$mc, nPerms, elements, nThreads))
    
    return(mapCodes(mcAllPerm(mcObj$mc, nPerms, NULL, nThreads), elements))
}
